class Skiplist {
    private static final int MAX_LEVEL = 16;
    private int[] headNext;
    private int[][] nodeNext;
    private int[] nodeVal;
    private int cnt = 0;
    private java.util.Random rand = new java.util.Random();
    public Skiplist() {
        headNext = new int[MAX_LEVEL];
        java.util.Arrays.fill(headNext, -1);
        nodeNext = new int[50001][MAX_LEVEL];
        nodeVal = new int[50001];
    }
    private int randomLevel() {
        int lvl = 1;
        while (lvl < MAX_LEVEL && rand.nextDouble() < 0.5) lvl++;
        return lvl;
    }
    public boolean search(int target) {
        int[] cur = headNext;
        for (int i = MAX_LEVEL - 1; i >= 0; i--) {
            int idx = cur[i];
            while (idx != -1 && nodeVal[idx] < target) { cur = nodeNext[idx]; idx = cur[i]; }
            if (idx != -1 && nodeVal[idx] == target) return true;
        }
        return false;
    }
    public void add(int num) {
        int[][] prevs = new int[MAX_LEVEL][];
        int[] prevIdx = new int[MAX_LEVEL];
        int[] cur = headNext;
        for (int i = MAX_LEVEL - 1; i >= 0; i--) {
            int idx = cur[i];
            while (idx != -1 && nodeVal[idx] < num) { int[] nxt = nodeNext[idx]; prevs[i] = nxt; prevIdx[i] = i; cur = nxt; idx = cur[i]; }
            prevs[i] = cur; prevIdx[i] = i;
        }
        int lvl = randomLevel(), id = cnt++;
        nodeVal[id] = num;
        for (int i = 0; i < MAX_LEVEL; i++) nodeNext[id][i] = -1;
        for (int i = 0; i < lvl; i++) {
            nodeNext[id][i] = prevs[i][i];
            prevs[i][i] = id;
        }
    }
    public boolean erase(int num) {
        int[][] prevs = new int[MAX_LEVEL][];
        int[] cur = headNext;
        boolean found = false;
        for (int i = MAX_LEVEL - 1; i >= 0; i--) {
            int idx = cur[i];
            while (idx != -1 && nodeVal[idx] < num) { cur = nodeNext[idx]; idx = cur[i]; }
            prevs[i] = cur;
            if (idx != -1 && nodeVal[idx] == num) found = true;
        }
        if (!found) return false;
        int target = prevs[0][0];
        for (int i = 0; i < MAX_LEVEL; i++)
            if (prevs[i][i] == target) prevs[i][i] = nodeNext[target][i];
        return true;
    }
}
